//! A tiny re2c-compatible regular-expression engine.
//!
//! timelib's date parser is generated by re2c from parse_date.re. Rather than
//! hand-translating the generated DFA, this module parses the re2c rule
//! definitions (copied verbatim from parse_date.re) and builds a lazily
//! determinised NFA that implements re2c's matching semantics: longest match
//! wins, ties are resolved in favour of the rule listed first.

use std::collections::HashMap;

pub type ByteSet = [u64; 4];

fn set_has(s: &ByteSet, b: u8) -> bool {
    s[(b >> 6) as usize] & (1u64 << (b & 63)) != 0
}
fn set_add(s: &mut ByteSet, b: u8) {
    s[(b >> 6) as usize] |= 1u64 << (b & 63);
}

#[derive(Clone, Debug)]
pub enum Node {
    Set(ByteSet),
    Seq(Vec<Node>),
    Alt(Vec<Node>),
    Star(Box<Node>),
    Plus(Box<Node>),
    Opt(Box<Node>),
    Rep(Box<Node>, u32, u32),
}

struct Parser<'a> {
    s: &'a [u8],
    p: usize,
    defs: &'a HashMap<String, Node>,
}

impl<'a> Parser<'a> {
    fn peek(&self) -> u8 {
        *self.s.get(self.p).unwrap_or(&0)
    }
    fn skip_ws(&mut self) {
        loop {
            while self.p < self.s.len() && (self.s[self.p] as char).is_whitespace() {
                self.p += 1;
            }
            // comments /* ... */
            if self.s[self.p..].starts_with(b"/*") {
                if let Some(e) = self.s[self.p + 2..].windows(2).position(|w| w == b"*/") {
                    self.p += e + 4;
                    continue;
                }
            }
            break;
        }
    }
    fn parse_alt(&mut self) -> Node {
        let mut alts = vec![self.parse_seq()];
        loop {
            self.skip_ws();
            if self.peek() == b'|' {
                self.p += 1;
                alts.push(self.parse_seq());
            } else {
                break;
            }
        }
        if alts.len() == 1 {
            alts.pop().unwrap()
        } else {
            Node::Alt(alts)
        }
    }
    fn parse_seq(&mut self) -> Node {
        let mut items = Vec::new();
        loop {
            self.skip_ws();
            let c = self.peek();
            if c == 0 || c == b'|' || c == b')' || c == b';' {
                break;
            }
            items.push(self.parse_postfix());
        }
        if items.len() == 1 {
            items.pop().unwrap()
        } else {
            Node::Seq(items)
        }
    }
    fn parse_num(&mut self) -> u32 {
        let mut n = 0u32;
        while self.peek().is_ascii_digit() {
            n = n * 10 + (self.peek() - b'0') as u32;
            self.p += 1;
        }
        n
    }
    fn parse_postfix(&mut self) -> Node {
        let mut atom = self.parse_atom();
        loop {
            match self.peek() {
                b'?' => {
                    self.p += 1;
                    atom = Node::Opt(Box::new(atom));
                }
                b'*' => {
                    self.p += 1;
                    atom = Node::Star(Box::new(atom));
                }
                b'+' => {
                    self.p += 1;
                    atom = Node::Plus(Box::new(atom));
                }
                b'{' => {
                    self.p += 1;
                    let min = self.parse_num();
                    let max = if self.peek() == b',' {
                        self.p += 1;
                        self.parse_num()
                    } else {
                        min
                    };
                    assert_eq!(self.peek(), b'}');
                    self.p += 1;
                    atom = Node::Rep(Box::new(atom), min, max);
                }
                _ => break,
            }
        }
        atom
    }
    fn parse_escape(&mut self) -> u8 {
        // after backslash
        let c = self.peek();
        self.p += 1;
        match c {
            b'n' => b'\n',
            b't' => b'\t',
            b'0'..=b'7' => {
                let mut v = (c - b'0') as u32;
                for _ in 0..2 {
                    let d = self.peek();
                    if (b'0'..=b'7').contains(&d) {
                        v = v * 8 + (d - b'0') as u32;
                        self.p += 1;
                    }
                }
                v as u8
            }
            other => other,
        }
    }
    fn parse_atom(&mut self) -> Node {
        self.skip_ws();
        let c = self.peek();
        match c {
            b'(' => {
                self.p += 1;
                let n = self.parse_alt();
                self.skip_ws();
                assert_eq!(self.peek(), b')');
                self.p += 1;
                n
            }
            b'\'' | b'"' => {
                let ci = c == b'\'';
                self.p += 1;
                let mut seq = Vec::new();
                loop {
                    let ch = self.peek();
                    self.p += 1;
                    if ch == c {
                        break;
                    }
                    let b = if ch == b'\\' { self.parse_escape() } else { ch };
                    let mut set = [0u64; 4];
                    set_add(&mut set, b);
                    if ci && b.is_ascii_alphabetic() {
                        set_add(&mut set, b.to_ascii_lowercase());
                        set_add(&mut set, b.to_ascii_uppercase());
                    }
                    seq.push(Node::Set(set));
                }
                if seq.len() == 1 {
                    seq.pop().unwrap()
                } else {
                    Node::Seq(seq)
                }
            }
            b'[' => {
                self.p += 1;
                let mut negate = false;
                if self.peek() == b'^' {
                    negate = true;
                    self.p += 1;
                }
                let mut set = [0u64; 4];
                let mut prev: Option<u8> = None;
                loop {
                    let ch = self.peek();
                    self.p += 1;
                    if ch == b']' {
                        break;
                    }
                    if ch == b'-' && prev.is_some() && self.peek() != b']' {
                        let mut hi = self.peek();
                        self.p += 1;
                        if hi == b'\\' {
                            hi = self.parse_escape();
                        }
                        let lo = prev.unwrap();
                        for b in lo..=hi {
                            set_add(&mut set, b);
                        }
                        prev = None;
                        continue;
                    }
                    let b = if ch == b'\\' { self.parse_escape() } else { ch };
                    set_add(&mut set, b);
                    prev = Some(b);
                }
                if negate {
                    for w in set.iter_mut() {
                        *w = !*w;
                    }
                }
                Node::Set(set)
            }
            _ => {
                let start = self.p;
                while self.peek().is_ascii_alphanumeric() || self.peek() == b'_' {
                    self.p += 1;
                }
                let name = std::str::from_utf8(&self.s[start..self.p]).unwrap();
                match self.defs.get(name) {
                    Some(n) => n.clone(),
                    None => panic!("re2c: undefined name {name}"),
                }
            }
        }
    }
}

/// Parse a list of `name = expr;` definitions.
pub fn parse_definitions(text: &str) -> HashMap<String, Node> {
    let mut defs: HashMap<String, Node> = HashMap::new();
    for line in text.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with("/*") {
            continue;
        }
        let eq = line.find('=').unwrap();
        let name = line[..eq].trim().to_string();
        let body = line[eq + 1..].trim();
        let body = body.strip_suffix(';').unwrap_or(body);
        let node = {
            let mut p = Parser {
                s: body.as_bytes(),
                p: 0,
                defs: &defs,
            };
            p.parse_alt()
        };
        defs.insert(name, node);
    }
    defs
}

pub fn parse_expr(expr: &str, defs: &HashMap<String, Node>) -> Node {
    let mut p = Parser {
        s: expr.as_bytes(),
        p: 0,
        defs,
    };
    p.parse_alt()
}

#[derive(Default, Clone)]
struct NState {
    trans: Vec<(ByteSet, usize)>,
    eps: Vec<usize>,
}

struct Nfa {
    states: Vec<NState>,
}

impl Nfa {
    fn new_state(&mut self) -> usize {
        self.states.push(NState::default());
        self.states.len() - 1
    }
    fn build(&mut self, n: &Node) -> (usize, usize) {
        match n {
            Node::Set(s) => {
                let a = self.new_state();
                let b = self.new_state();
                self.states[a].trans.push((*s, b));
                (a, b)
            }
            Node::Seq(items) => {
                let (s, mut e) = self.build(&items[0]);
                for it in &items[1..] {
                    let (s2, e2) = self.build(it);
                    self.states[e].eps.push(s2);
                    e = e2;
                }
                (s, e)
            }
            Node::Alt(items) => {
                let a = self.new_state();
                let b = self.new_state();
                for it in items {
                    let (s, e) = self.build(it);
                    self.states[a].eps.push(s);
                    self.states[e].eps.push(b);
                }
                (a, b)
            }
            Node::Star(inner) => {
                let a = self.new_state();
                let b = self.new_state();
                let (s, e) = self.build(inner);
                self.states[a].eps.push(s);
                self.states[a].eps.push(b);
                self.states[e].eps.push(s);
                self.states[e].eps.push(b);
                (a, b)
            }
            Node::Plus(inner) => {
                let (s, e) = self.build(inner);
                let b = self.new_state();
                self.states[e].eps.push(s);
                self.states[e].eps.push(b);
                (s, b)
            }
            Node::Opt(inner) => {
                let a = self.new_state();
                let b = self.new_state();
                let (s, e) = self.build(inner);
                self.states[a].eps.push(s);
                self.states[a].eps.push(b);
                self.states[e].eps.push(b);
                (a, b)
            }
            Node::Rep(inner, min, max) => {
                let a = self.new_state();
                let mut cur = a;
                for _ in 0..*min {
                    let (s, e) = self.build(inner);
                    self.states[cur].eps.push(s);
                    cur = e;
                }
                let end = self.new_state();
                self.states[cur].eps.push(end);
                for _ in *min..*max {
                    let (s, e) = self.build(inner);
                    self.states[cur].eps.push(s);
                    self.states[e].eps.push(end);
                    cur = e;
                }
                (a, end)
            }
        }
    }
}

const UNCOMPUTED: u32 = u32::MAX;
const DEAD: u32 = u32::MAX - 1;

struct DState {
    nfa_states: Vec<usize>,
    accept: Option<usize>,
    next: Box<[u32; 256]>,
}

/// A multi-rule scanner with lex/re2c semantics.
pub struct Scanner {
    nfa: Nfa,
    accept_of: Vec<Option<usize>>,
    dstates: Vec<DState>,
    dmap: HashMap<Vec<usize>, u32>,
    start: u32,
}

impl Scanner {
    pub fn new(rules: &[Node]) -> Self {
        let mut nfa = Nfa { states: Vec::new() };
        let start = nfa.new_state();
        let mut accepts = Vec::new();
        for (idx, r) in rules.iter().enumerate() {
            let (s, e) = nfa.build(r);
            nfa.states[start].eps.push(s);
            accepts.push((e, idx));
        }
        let mut accept_of = vec![None; nfa.states.len()];
        for (e, idx) in accepts {
            accept_of[e] = Some(idx);
        }
        let mut sc = Scanner {
            nfa,
            accept_of,
            dstates: Vec::new(),
            dmap: HashMap::new(),
            start: 0,
        };
        let closure = sc.closure(vec![start]);
        sc.start = sc.intern(closure);
        sc
    }

    fn closure(&self, mut stack: Vec<usize>) -> Vec<usize> {
        let mut seen = vec![false; self.nfa.states.len()];
        let mut out = Vec::new();
        while let Some(s) = stack.pop() {
            if seen[s] {
                continue;
            }
            seen[s] = true;
            out.push(s);
            for &e in &self.nfa.states[s].eps {
                if !seen[e] {
                    stack.push(e);
                }
            }
        }
        out.sort_unstable();
        out
    }

    fn intern(&mut self, set: Vec<usize>) -> u32 {
        if let Some(&id) = self.dmap.get(&set) {
            return id;
        }
        let accept = set.iter().filter_map(|&s| self.accept_of[s]).min();
        let id = self.dstates.len() as u32;
        self.dstates.push(DState {
            nfa_states: set.clone(),
            accept,
            next: Box::new([UNCOMPUTED; 256]),
        });
        self.dmap.insert(set, id);
        id
    }

    fn step(&mut self, d: u32, b: u8) -> u32 {
        let n = self.dstates[d as usize].next[b as usize];
        if n != UNCOMPUTED {
            return n;
        }
        let mut targets = Vec::new();
        for &s in &self.dstates[d as usize].nfa_states {
            for (set, t) in &self.nfa.states[s].trans {
                if set_has(set, b) {
                    targets.push(*t);
                }
            }
        }
        let res = if targets.is_empty() {
            DEAD
        } else {
            let cl = self.closure(targets);
            self.intern(cl)
        };
        self.dstates[d as usize].next[b as usize] = res;
        res
    }

    /// Longest match starting at `pos` in `buf` (bytes beyond buf are not
    /// consumed). Returns (rule index, end position).
    pub fn longest_match(&mut self, buf: &[u8], pos: usize) -> Option<(usize, usize)> {
        let mut d = self.start;
        let mut best: Option<(usize, usize)> = None;
        let mut p = pos;
        loop {
            if let Some(r) = self.dstates[d as usize].accept {
                if p > pos {
                    best = Some((r, p));
                }
            }
            if p >= buf.len() {
                break;
            }
            let nd = self.step(d, buf[p]);
            if nd == DEAD {
                break;
            }
            d = nd;
            p += 1;
        }
        best
    }
}
